  'form.issue.required': ['Erforderliches Feld ist leer.', 'Required field is empty.', 'Обязательное поле не заполнено.', 'Il campo obbligatorio è vuoto.', 'El campo obligatorio está vacío.', '必須フィールドが空です。', '必填字段为空。'],
