  'conversion.status.batch': ['Stapel: {{documents}} Dokumente, {{pages}} Seiten, {{bytes}} Byte Ausgabe.', 'Batch: {{documents}} document(s), {{pages}} page(s), {{bytes}} output bytes.', 'Пакет: документов — {{documents}}, страниц — {{pages}}, выходных байт — {{bytes}}.', 'Batch: {{documents}} documenti, {{pages}} pagine, {{bytes}} byte in uscita.', 'Lote: {{documents}} documentos, {{pages}} páginas, {{bytes}} bytes de salida.', '一括処理: {{documents}} 件、{{pages}} ページ、出力 {{bytes}} バイト。', '批量：{{documents}} 个文档、{{pages}} 页、输出 {{bytes}} 字节。'],
  'conversion.status.imagesPrepared': ['{{count}} lokale Rasterbilder für die PDF-Erstellung vorbereitet.', '{{count}} local raster image(s) prepared for PDF creation.', 'Подготовлено локальных растровых изображений: {{count}}.', 'Immagini raster locali preparate per la creazione PDF: {{count}}.', 'Imágenes rasterizadas locales preparadas para crear el PDF: {{count}}.', 'PDF 作成用にローカルのラスター画像を {{count}} 件準備しました。', '已为创建 PDF 准备 {{count}} 张本地栅格图像。'],
  'conversion.status.created': ['{{sources}} Workspace-Quellen und {{images}} lokale Bilder ergaben {{pages}} PDF-Seiten.', 'Created {{pages}} PDF page(s) from {{sources}} workspace source(s) and {{images}} local image(s).', 'Из источников Workspace ({{sources}}) и локальных изображений ({{images}}) создано страниц PDF: {{pages}}.', 'Create {{pages}} pagine PDF da {{sources}} fonti Workspace e {{images}} immagini locali.', 'Se crearon {{pages}} páginas PDF a partir de {{sources}} fuentes de Workspace e {{images}} imágenes locales.', 'Workspace ソース {{sources}} 件とローカル画像 {{images}} 件から PDF ページ {{pages}} 件を作成しました。', '从 {{sources}} 个 Workspace 来源和 {{images}} 张本地图像创建了 {{pages}} 个 PDF 页面。'],
  'conversion.status.raster': ['Rasterexport: {{pages}} Seiten → {{format}} bei {{dpi}} DPI.', 'Raster export: {{pages}} page(s) → {{format}} at {{dpi}} DPI.', 'Растровый экспорт: страниц — {{pages}}, формат — {{format}}, {{dpi}} DPI.', 'Esportazione raster: {{pages}} pagine → {{format}} a {{dpi}} DPI.', 'Exportación rasterizada: {{pages}} páginas → {{format}} a {{dpi}} DPI.', 'ラスター書き出し: {{pages}} ページ → {{format}}、{{dpi}} DPI。', '栅格导出：{{pages}} 页 → {{format}}，{{dpi}} DPI。'],
  'conversion.error': ['Die PDF-Aktion konnte nicht abgeschlossen werden.', 'The PDF operation could not be completed.', 'Не удалось выполнить операцию с PDF.', 'Impossibile completare l’operazione PDF.', 'No se pudo completar la operación con PDF.', 'PDF 操作を完了できませんでした。', '无法完成 PDF 操作。'],
  'conversion.warning.mixedSources': ['Workspace-Quellen werden semantisch in PDF-Studio-Seiten neu angeordnet. Exakte Koordinaten der Quell-App bleiben nur erhalten, wenn das kanonische Modell sie bereitstellt.', 'Workspace sources are semantically reflowed into PDF Studio pages; exact source-app coordinates are preserved only where the canonical source exposes them.', 'Источники Workspace семантически переоформляются в страницы PDF Studio; точные координаты исходного приложения сохраняются, только если они доступны в канонической модели.', 'Le fonti Workspace vengono reimpaginate semanticamente nelle pagine PDF Studio; le coordinate esatte dell’app di origine sono preservate solo se esposte dalla fonte canonica.', 'Las fuentes de Workspace se reorganizan semánticamente en páginas de PDF Studio; las coordenadas exactas solo se conservan cuando las expone la fuente canónica.', 'Workspace ソースは意味を保って PDF Studio ページに再配置されます。ソースアプリの正確な座標は、正規ソースが提供する場合のみ保持されます。', 'Workspace 来源会按语义重排为 PDF Studio 页面；只有规范来源提供的源应用精确坐标才会保留。'],
  'conversion.warning.invalidLinks': ['Sicherheitsrichtlinie hat {{count}} ungültige oder nicht-HTTP(S)-Linkziele ausgelassen.', '{{count}} invalid or non-HTTP(S) link target(s) were omitted by the conversion safety policy.', 'Политика безопасности исключила недопустимых ссылок или ссылок не HTTP(S): {{count}}.', 'La policy di sicurezza della conversione ha omesso destinazioni di collegamento non valide o non HTTP(S): {{count}}.', 'La política de seguridad de conversión omitió destinos de enlace no válidos o que no usan HTTP(S): {{count}}.', '変換の安全ポリシーにより、無効または HTTP(S) 以外のリンク先を {{count}} 件省略しました。', '转换安全策略省略了 {{count}} 个无效或非 HTTP(S) 链接目标。'],
  'conversion.warning.generic': ['Einige Inhalte konnten nicht übernommen werden.', 'Some content could not be carried over.', 'Некоторые данные не удалось перенести.', 'Alcuni contenuti non sono stati trasferiti.', 'No se pudo transferir parte del contenido.', '一部の内容を引き継げませんでした。', '部分内容无法保留。'],

