  'password.vault.unavailable': ['Native KeyVault ist nicht verfügbar.', 'Native KeyVault is unavailable.', 'Нативный KeyVault недоступен.', 'KeyVault nativo non disponibile.', 'KeyVault nativo no disponible.', 'ネイティブ KeyVault を利用できません。', '本机 KeyVault 不可用。'],
  // DEF-RE-022 (Runde 357): die Aenderungsrechte waren im Dialog nicht waehlbar — `permissions: -4`
  // stand fest verdrahtet in `PdfPasswordProtectionModal.tsx:72`, und die Oberflaeche hatte keinen
  // einzigen Zustandshaken dafuer. Die Anforderung AST-0867 verlangt woertlich "Passwortschutz und
  // Berechtigungen". Bit-Semantik aus dem eigenen Test der Datei: `-4` laesst alle Rechte zu;
  // ein verweigertes Recht loescht sein Bit (1-basiert 3 drucken, 4 aendern, 5 kopieren, 6 kommentieren
  // — 0-basiert 2, 3, 4, 5).
  'password.permissions': ['Änderungsrechte', 'Permissions', 'Разрешения', 'Autorizzazioni', 'Permisos', '権限', '权限'],
  'password.permission.print': ['Drucken erlauben', 'Allow printing', 'Разрешить печать', 'Consenti stampa', 'Permitir impresión', '印刷を許可', '允许打印'],
  'password.permission.modify': ['Ändern erlauben', 'Allow modifying', 'Разрешить изменение', 'Consenti modifica', 'Permitir modificación', '変更を許可', '允许修改'],
  'password.permission.copy': ['Kopieren erlauben', 'Allow copying', 'Разрешить копирование', 'Consenti copia', 'Permitir copia', 'コピーを許可', '允许复制'],
  'password.permission.annotate': ['Kommentieren erlauben', 'Allow annotating', 'Разрешить комментирование', 'Consenti annotazioni', 'Permitir anotaciones', '注釈を許可', '允许注释'],
  'password.policy': ['Aus Gründen der Standardkonformität werden derzeit nur druckbare ASCII-Passwörter akzeptiert. Nicht-ASCII-Passwörter werden abgelehnt, bis SASLprep implementiert ist; eine Unicode-Normalisierung wird nicht vorgetäuscht.', 'For standards correctness, only printable ASCII passwords are accepted. Non-ASCII passwords fail closed until SASLprep is implemented; Unicode normalization is not treated as equivalent.', 'Для соответствия стандарту принимаются только печатные пароли ASCII. Пароли вне ASCII отклоняются до реализации SASLprep; нормализация Unicode не считается эквивалентной.', 'Per conformità agli standard sono accettate solo password ASCII stampabili. Le password non ASCII vengono rifiutate finché non sarà implementato SASLprep; la normalizzazione Unicode non viene considerata equivalente.', 'Para cumplir los estándares, solo se aceptan contraseñas ASCII imprimibles. Las contraseñas no ASCII se rechazan hasta implementar SASLprep; la normalización Unicode no se considera equivalente.', '標準準拠のため、現在は印字可能な ASCII パスワードのみ受け付けます。SASLprep の実装までは非 ASCII パスワードを拒否し、Unicode 正規化を同等とは扱いません。', '为符合标准，目前仅接受可打印 ASCII 密码。实现 SASLprep 前会拒绝非 ASCII 密码，不会将 Unicode 规范化视为等效处理。'],
  'password.encrypting': ['Wird lokal verschlüsselt…', 'Encrypting locally…', 'Локальное шифрование…', 'Crittografia locale…', 'Cifrando localmente…', 'ローカルで暗号化しています…', '正在本地加密…'],
  'password.export': ['Geschütztes PDF exportieren', 'Export protected PDF', 'Экспортировать защищённый PDF', 'Esporta PDF protetto', 'Exportar PDF protegido', '保護された PDF をエクスポート', '导出受保护的 PDF'],
  'password.error.ownerMismatch': ['Die Bestätigung des Besitzerpassworts stimmt nicht überein.', 'Owner password confirmation does not match.', 'Подтверждение пароля владельца не совпадает.', 'La conferma della password del proprietario non corrisponde.', 'La confirmación de la contraseña del propietario no coincide.', '所有者パスワードの確認が一致しません。', '所有者密码确认不匹配。'],
  'password.error.distinct': ['Benutzer- und Besitzerpasswort müssen unterschiedlich sein.', 'User and owner passwords must be distinct.', 'Пароли пользователя и владельца должны различаться.', 'Le password utente e proprietario devono essere diverse.', 'Las contraseñas de usuario y propietario deben ser distintas.', 'ユーザーと所有者のパスワードは別々にしてください。', '用户密码和所有者密码必须不同。'],
