const LOCALE_INDEX: Readonly<Record<WorkspaceLocale, number>> = {
  'de-DE': 0, 'en-US': 1, 'ru-RU': 2, 'it-IT': 3, 'es-ES': 4, 'ja-JP': 5, 'zh-CN': 6,
};

export type PdfWorkflowCopyKey = keyof typeof PDF_WORKFLOW_MESSAGES;

export function pdfWorkflowText(
  locale: WorkspaceLocale,
  key: PdfWorkflowCopyKey,
  values: Readonly<Record<string, string | number>> = {},
): string {
  const template = PDF_WORKFLOW_MESSAGES[key][LOCALE_INDEX[locale]];
  return template.replace(/\{\{([a-zA-Z]+)\}\}/gu, (_placeholder, name: string) => {
    const value = values[name];
    return typeof value === 'number' ? new Intl.NumberFormat(locale).format(value) : value ?? '';
  });
}

export function pdfWorkflowMessageKeys(): readonly PdfWorkflowCopyKey[] {
  return Object.keys(PDF_WORKFLOW_MESSAGES) as PdfWorkflowCopyKey[];
}
